'use strict';

const $ = selector => document.querySelector(selector);
const fallbackTaxonomy = window.SultraTaxonomy || { CATEGORIES: [], REGIONS: [], ALL_DISTRICTS: [] };
const icons = Object.fromEntries(fallbackTaxonomy.CATEGORIES.map(category => [category.slug, category.icon]));
const state = { categories: [], regions: [], page: 1, totalPages: 1, category: '', radius: '10', minPrice: '', maxPrice: '', view: 'grid', searchTimer: null, suggestionTimer: null, sellerSession: null, listingBusy: false, compare: [], recent: [] };

const rupiah = value => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(Number(value || 0));
const esc = value => String(value ?? '').replace(/[&<>"']/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' }[character]));
const safeImage = value => { const url = String(value || ''); return /^\/(?!\/)|^https:\/\//.test(url) ? url.replace(/['"\\\n\r]/g, '') : ''; };
const safeVideo = value => { const url = String(value || ''); return /^\/(?!\/)|^https:\/\//.test(url) ? url.replace(/['"\\\n\r]/g, '') : ''; };

// Robust API client: GET requests have a bounded timeout and one safe retry; mutations are never retried automatically.
async function api(url, options = {}) {
  const method = String(options.method || 'GET').toUpperCase();
  const maxAttempts = method === 'GET' ? 2 : 1;
  let lastError;
  for (let attempt = 0; attempt < maxAttempts; attempt += 1) {
    const controller = new AbortController();
    const timeout = window.setTimeout(() => controller.abort(), 10000);
    try {
      const response = await fetch(url, { ...options, signal: controller.signal });
      const body = await response.json().catch(() => ({}));
      if (!response.ok || body.success === false) { const error = new Error(body.error || 'Permintaan gagal. Coba lagi.'); error.code = body.code; error.status = response.status; throw error; }
      return body;
    } catch (error) {
      lastError = error.name === 'AbortError' ? new Error('Request timeout. Periksa koneksi Anda.') : error;
      const retryable = method === 'GET' && (!error.status || error.status >= 500 || error.name === 'AbortError');
      if (!retryable || attempt === maxAttempts - 1) throw lastError;
      await new Promise(resolve => window.setTimeout(resolve, 350));
    } finally { window.clearTimeout(timeout); }
  }
  throw lastError;
}

function toast(message, tone = 'normal') {
  const element = $('#toast');
  if (!element) return;
  element.textContent = message;
  element.dataset.tone = tone;
  element.classList.add('show');
  clearTimeout(window.toastTimer);
  window.toastTimer = setTimeout(() => element.classList.remove('show'), 3200);
}

function track(eventName, listingId = null) {
  const payload = { event_name: eventName, path: location.pathname + location.hash, listing_id: listingId, referrer: document.referrer || null };
  if (navigator.sendBeacon) navigator.sendBeacon('/api/analytics/track', new Blob([JSON.stringify(payload)], { type: 'application/json' }));
  else fetch('/api/analytics/track', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(payload), keepalive: true }).catch(() => {});
}

function getFavorites() { try { return JSON.parse(localStorage.getItem('sultra-favs') || '[]').map(Number); } catch (error) { console.error('[favorites]', error); return []; } }
function setFavorites(ids) { localStorage.setItem('sultra-favs', JSON.stringify([...new Set(ids)])); $('#favorite-count').textContent = ids.length; }
function refreshFavoriteCount() { setFavorites(getFavorites()); }
function readLocalArray(key) { try { const value = JSON.parse(localStorage.getItem(key) || '[]'); return Array.isArray(value) ? value : []; } catch { return []; } }
function writeLocalArray(key, value, limit = 12) { localStorage.setItem(key, JSON.stringify(value.slice(0, limit))); }
function saveSearchHistory(query) { const clean = String(query || '').trim(); if (clean.length < 2) return; const items = readLocalArray('sultra-search-history').filter(item => item !== clean); writeLocalArray('sultra-search-history', [clean, ...items], 8); }
function saveRecentlyViewed(listing) { if (!listing?.id) return; const items = readLocalArray('sultra-recently-viewed').filter(item => Number(item.id) !== Number(listing.id)); writeLocalArray('sultra-recently-viewed', [{ id: Number(listing.id), title: listing.title, price: Number(listing.price || 0), image_url: listing.image_url || '', category_name: listing.category_name || 'Marketplace', category_slug: listing.category_slug || '', district: listing.district || listing.city || 'Kendari', seller_name: listing.seller_name || 'Seller lokal', seller_verified: listing.seller_verified || 0, seller_rating: listing.seller_rating || 0, seller_review_count: listing.seller_review_count || 0, created_at: listing.created_at || null }, ...items], 8); state.recent = readLocalArray('sultra-recently-viewed'); renderRecentlyViewed(); }
function getCompareItems() { return readLocalArray('sultra-compare'); }
function reactionCount(id) { const reactions = readLocalArray('sultra-reactions'); return Number(reactions.find(item => Number(item.id) === Number(id))?.count || 0); }
function toggleReaction(id, button) { const reactions = readLocalArray('sultra-reactions').filter(item => Number(item.id) !== Number(id)); const nextCount = reactionCount(id) + (button.dataset.reacted === 'true' ? -1 : 1); if (nextCount > 0) reactions.unshift({ id: Number(id), count: nextCount }); writeLocalArray('sultra-reactions', reactions, 60); button.dataset.reacted = nextCount > reactionCount(id) ? 'true' : 'false'; button.textContent = `♥ ${Math.max(0, nextCount)}`; button.classList.toggle('saved', nextCount > 0); }
function setCompareItems(items) { state.compare = items.slice(0, 3); writeLocalArray('sultra-compare', state.compare, 3); updateCompareTray(); }
function shareListing(title) { const text = `${title} — lihat di SultraKita`; if (navigator.share) navigator.share({ title, text, url: location.href }).catch(() => {}); else navigator.clipboard?.writeText(location.href).then(() => toast('Link listing disalin.')).catch(() => toast('Salin URL halaman ini untuk berbagi.')); }
function shareChannel(channel, listing) { const url = window.SultraBridge?.canonicalUrl(listing) || location.href; const text = `${listing?.title || 'Listing SultraKita'} — ${rupiah(listing?.price)} · ${listing?.district || 'Kendari'}`; if (channel === 'whatsapp') window.open(`https://wa.me/?text=${encodeURIComponent(`${text}\n${url}`)}`, '_blank', 'noopener,noreferrer'); else if (channel === 'facebook') navigator.clipboard?.writeText(text + `\n${url}`).then(() => toast('Caption Facebook disalin.')).catch(() => toast('Salin caption secara manual dari detail listing.')); else navigator.clipboard?.writeText(url).then(() => toast('Link listing disalin.')).catch(() => toast('Salin URL halaman ini untuk berbagi.')); }

function externalCard(card) { const image = safeImage(card.image_url); const imageStyle = image ? ` style="background-image:url('${esc(image)}')"` : ''; const categoryIcon = icons[card.category_slug] || '↗'; return `<article class="listing external-listing-card fade-in" data-external-url="${esc(card.url)}"><div class="listing-image ${image ? 'has-image' : ''}"${imageStyle}><span>${categoryIcon}</span><span class="listing-badge">Sumber</span></div><div class="listing-body"><span class="partner-source">${esc(card.source_label || 'Sumber eksternal')}</span><h3>${esc(card.title)}</h3>${card.price ? `<div class="listing-price">${rupiah(card.price)}</div>` : ''}<div class="listing-meta">${esc(card.category_name || 'Marketplace')} · ${esc(card.city || 'Kendari')}</div><p class="external-card-description">${esc(card.description || 'Ringkasan singkat tersedia di sumber asli.')}</p><div class="listing-actions"><a class="mini-action" href="${esc(card.url)}" target="_blank" rel="noopener noreferrer">Buka sumber ↗</a></div></div></article>`; }

function listingCard(listing) { window.__listingCache = window.__listingCache || new Map(); window.__listingCache.set(Number(listing.id), listing);
  const saved = getFavorites().includes(Number(listing.id));
  const image = safeImage(listing.image_url);
  const verified = Number(listing.seller_verified) ? '<span class="verified-mark" title="Seller terverifikasi">✓</span>' : ''; const verifiedBadge = Number(listing.seller_verified) ? '<span class="badge-verified">✓ Terverifikasi</span>' : ''; const imageCount = Number(listing.image_count || listing.images_count || 0) > 1 ? `<span class="image-count">▧ ${Number(listing.image_count || listing.images_count)}</span>` : '';
  const video = safeVideo(listing.video_url); const webp = safeImage(listing.image_webp_url); const avif = safeImage(listing.image_avif_url); const imageMarkup = image ? `<picture class="listing-picture">${avif ? `<source srcset="${esc(avif)}" type="image/avif">` : ''}${webp ? `<source srcset="${esc(webp)}" type="image/webp">` : ''}<img src="${esc(image)}" alt="${esc(listing.title)}" loading="lazy" decoding="async" width="400" height="300"></picture>` : `<span>${icons[listing.category_slug] || '＋'}</span>`;
  return `<article class="listing listing-card-v2 fade-in" data-open-listing="${Number(listing.id)}" tabindex="0" aria-label="Buka listing ${esc(listing.title)}"><div class="listing-image card-media ${image ? 'has-image' : ''}">${video ? `<video class="listing-video-preview" muted playsinline loop autoplay preload="metadata"><source src="${esc(video)}"></video>` : imageMarkup}<span class="listing-badge">${listing.created_at ? 'Baru' : 'Pilihan'}</span>${verifiedBadge}${listing.has_video ? '<span class="video-badge">▶ Video</span>' : ''}${imageCount}</div><div class="listing-body card-body"><div class="card-price-row"><div class="listing-price card-price">${rupiah(listing.price)}</div></div><h3 class="card-title">${esc(listing.title)}</h3><div class="listing-meta card-meta"><span>⌖ ${esc(listing.district || listing.city || 'Kendari')}</span><span>${esc(listing.category_name || 'Marketplace')}</span></div><div class="card-tags"><span class="tag">${esc(listing.category_name || 'Lokal')}</span></div><div class="seller-line seller-info"><span class="seller-avatar seller-avatar-sm">${esc(String(listing.seller_name || 'S').slice(0, 1).toUpperCase())}</span><span class="seller-name">${esc(listing.seller_name || 'Seller lokal')}</span>${verified}<span class="seller-rating">★ ${Number(listing.seller_rating || 0).toFixed(1)} <small>(${Number(listing.seller_review_count || 0)})</small></span></div><div class="listing-actions card-actions"><button class="mini-action ${saved ? 'saved' : ''}" data-action="favorite" data-id="${Number(listing.id)}">${saved ? '♥ Tersimpan' : '♡ Simpan'}</button><button class="mini-action" data-action="share" data-title="${esc(listing.title)}">↗ Bagikan</button><button class="mini-action" data-action="compare" data-id="${Number(listing.id)}">⇄ Bandingkan</button><button class="mini-action reaction-action" data-action="react" data-id="${Number(listing.id)}">♥ ${reactionCount(Number(listing.id))}</button><button class="mini-action" data-action="ask">Tanya</button><button class="mini-action" data-action="fb-copy">FB</button><button class="mini-action" data-action="flyer">Flyer</button></div></div></article>`;
}

async function loadStats() { try { const result = await api('/api/stats'); const summary = result.data?.summary || {}; $('#total-listings').textContent = Number(summary.active_listings ?? summary.total_listings ?? 0).toLocaleString('id-ID'); $('#covered-districts').textContent = Number(summary.covered_districts || 0).toLocaleString('id-ID'); $('#weekly-new-listings').textContent = Number(summary.weekly_new_listings || 0).toLocaleString('id-ID'); } catch (error) { console.error('[stats]', error); $('#total-listings').textContent = '0'; $('#covered-districts').textContent = '0'; $('#weekly-new-listings').textContent = '0'; const status = $('#stats-status'); if (status) status.textContent = 'Statistik sementara belum tersedia; data akan diperbarui saat koneksi pulih.'; } }

function renderCategories() {
  $('#categories').innerHTML = state.categories.map(category => `<button class="category ${state.category === category.slug ? 'active' : ''}" data-category="${esc(category.slug)}" aria-label="Jelajahi ${esc(category.name)}"><div class="category-icon">${icons[category.slug] || '＋'}</div><strong>${esc(category.name)}</strong><small>Jelajahi kategori</small></button>`).join('');
  const formCategory = $('#form-category');
  if (formCategory) formCategory.innerHTML = '<option value="">Pilih kategori</option>' + state.categories.map(category => `<option value="${Number(category.id)}">${esc(category.name)}</option>`).join('');
}

async function loadCategories() { try { const result = await api('/api/categories'); state.categories = result.data?.length ? result.data : fallbackTaxonomy.CATEGORIES; if (result.meta?.source === 'fallback') toast('Mode offline: kategori bawaan ditampilkan.', 'warn'); } catch (error) { console.error('[categories]', error); state.categories = fallbackTaxonomy.CATEGORIES; toast('Daftar kategori offline dipakai sementara.', 'warn'); } renderCategories(); }

function setLoading() { $('#listings').innerHTML = '<div class="skeleton skeleton-card"></div>'.repeat(4); }
function emptyState(query) { return `<div class="empty"><div><strong>${query ? `Tidak menemukan “${esc(query)}”` : 'Belum ada listing di sini'}</strong><span>Coba kata kunci lain, perluas wilayah, atau jadilah yang pertama memasang iklan.</span></div></div>`; }
function updateActiveFilter() { const row = $('#active-filter-row'); const clear = $('#clear-filter'); const label = state.category ? (state.categories.find(item => item.slug === state.category)?.name || state.category) : ''; row.hidden = !label; if (label) clear.textContent = `${label} ×`; document.querySelectorAll('.filter-chip').forEach(chip => chip.classList.toggle('active', !state.category)); }
function syncDiscoveryUrl({ replace = false } = {}) { const url = new URL(location.href); const query = $('#search').value.trim(); state.category ? url.searchParams.set('category', state.category) : url.searchParams.delete('category'); query ? url.searchParams.set('q', query) : url.searchParams.delete('q'); $('#district').value ? url.searchParams.set('district', $('#district').value) : url.searchParams.delete('district'); $('#sort').value !== 'newest' ? url.searchParams.set('sort', $('#sort').value) : url.searchParams.delete('sort'); state.radius !== '10' ? url.searchParams.set('radius', state.radius) : url.searchParams.delete('radius'); state.minPrice ? url.searchParams.set('min_price', state.minPrice) : url.searchParams.delete('min_price'); state.maxPrice ? url.searchParams.set('max_price', state.maxPrice) : url.searchParams.delete('max_price'); const next = `${url.pathname}${url.search}${url.hash}`; (replace ? history.replaceState : history.pushState).call(history, null, '', next); }

async function loadListings({ reset = true } = {}) {
  const listings = $('#listings'); listings?.setAttribute('aria-busy', 'true');
  if (reset) { state.page = 1; setLoading(); }
  const query = $('#search').value.trim(); saveSearchHistory(query); const params = new URLSearchParams({ q: query, district: $('#district').value, sort: $('#sort').value, page: state.page, limit: 8, radius_km: state.radius, min_price: state.minPrice, max_price: state.maxPrice });
  if (state.category) params.set('category', state.category);
  [...params].forEach(([key, value]) => { if (!value) params.delete(key); });
  try {
    const [result, external] = await Promise.all([api(`/api/listings?${params}`), api(`/api/external-cards?${params.toString()}`)]);
    state.totalPages = Number(result.meta?.total_pages || 1);
    if (query.length >= 2 && authToken()) api('/api/search-history', { method: 'POST', headers: { 'content-type': 'application/json', authorization: `Bearer ${authToken()}` }, body: JSON.stringify({ query, results_count: Number(result.meta?.total || 0) }) }).catch(() => {});
    const items = result.data || [];
    const externalItems = reset ? (external.data || []) : [];
    $('#result-summary').textContent = `${Number(result.meta?.total || items.length).toLocaleString('id-ID')} listing lokal${externalItems.length ? ` + ${externalItems.length} sumber eksternal` : ''} · Kendari dan Sultra`;
    if (reset) $('#listings').innerHTML = items.length || externalItems.length ? items.map(listingCard).join('') + externalItems.map(externalCard).join('') : emptyState($('#search').value.trim());
    else if (items.length) $('#listings').insertAdjacentHTML('beforeend', items.map(listingCard).join(''));
    $('#load-more').hidden = state.page >= state.totalPages || !items.length;
    updateActiveFilter();
  } catch (error) { $('#listings').innerHTML = `<div class="empty"><div><strong>Listing belum bisa dimuat</strong><span>${esc(error.message)}</span></div></div>`; $('#load-more').hidden = true; } finally { listings?.setAttribute('aria-busy', 'false'); }
}

async function renderSuggestions() {
  const input = $('#search'); const box = $('#suggestions'); const query = input.value.trim();
  if (query.length < 2) { const history = readLocalArray('sultra-search-history'); box.innerHTML = history.length ? `<div class="suggestion-history-head"><strong>Pencarian terakhir</strong><button type="button" data-clear-history>Hapus</button></div>${history.map(item => `<button class="suggestion" data-suggestion="${esc(item)}"><span class="suggestion-icon">◷</span><span><strong>${esc(item)}</strong><small>Riwayat pencarian</small></span></button>`).join('')}` : ''; box.hidden = !history.length; box.querySelector('[data-clear-history]')?.addEventListener('click', event => { event.stopPropagation(); localStorage.removeItem('sultra-search-history'); box.hidden = true; }); return; }
  try { const result = await api(`/api/listings?q=${encodeURIComponent(query)}&limit=5`); const rows = result.data || []; box.innerHTML = rows.length ? rows.map(row => `<button class="suggestion" data-suggestion="${esc(row.title)}"><span class="suggestion-icon">${icons[row.category_slug] || '＋'}</span><span><strong>${esc(row.title)}</strong><small>${esc(row.category_name || 'Listing')} · ${esc(row.district || 'Kendari')}</small></span></button>`).join('') : `<div class="suggestion"><span><strong>Tekan Enter untuk mencari</strong><small>${esc(query)}</small></span></div>`; box.hidden = false; } catch (error) { console.error('[suggestions]', error); box.hidden = true; }
}

let authUserIdPromise;
async function resolveAuthUserId() { const token = authToken(); if (!token) return null; if (!authUserIdPromise) authUserIdPromise = api('/api/me', { headers: { authorization: `Bearer ${token}` } }).then(result => Number(result.data?.id) || null).catch(() => null); return authUserIdPromise; }
async function toggleFavorite(id, button) {
  const favorites = getFavorites(); const wasFavorited = favorites.includes(id); const next = wasFavorited ? favorites.filter(value => value !== id) : [...favorites, id];
  setFavorites(next); button.classList.toggle('saved', next.includes(id)); button.textContent = next.includes(id) ? '♥ Tersimpan' : '♡ Simpan'; button.classList.add('heart-pop'); setTimeout(() => button.classList.remove('heart-pop'), 420); toast(next.includes(id) ? 'Listing disimpan ke favorit.' : 'Listing dihapus dari favorit.');
  // Keep offline-first behavior, then sync authenticated users with the existing API contract.
  const userId = await resolveAuthUserId(); if (!userId) return;
  try { await api('/api/favorites', { method: wasFavorited ? 'DELETE' : 'POST', headers: { 'content-type': 'application/json', authorization: `Bearer ${authToken()}` }, body: JSON.stringify({ user_id: userId, listing_id: Number(id) }) }); } catch (error) { console.warn('[favorites-sync]', error.message); toast('Favorit tersimpan lokal; sinkronisasi server tertunda.', 'warn'); }
}
function authToken() { if (localStorage.getItem('sultra-account-token')) return localStorage.getItem('sultra-account-token'); if (localStorage.getItem('sultra-auth-token')) return localStorage.getItem('sultra-auth-token'); if (localStorage.getItem('sultra-token')) return localStorage.getItem('sultra-token'); try { return JSON.parse(sessionStorage.getItem('sultra-seller-session') || 'null')?.token || sessionStorage.getItem('sultra-auth-token') || ''; } catch { return sessionStorage.getItem('sultra-auth-token') || ''; } }
function toggleCompare(listing) { const items = getCompareItems(); const exists = items.some(item => Number(item.id) === Number(listing.id)); if (exists) setCompareItems(items.filter(item => Number(item.id) !== Number(listing.id))); else if (items.length >= 3) toast('Maksimal 3 listing untuk dibandingkan.', 'warn'); else setCompareItems([...items, { id: Number(listing.id), title: listing.title, price: Number(listing.price || 0), category_name: listing.category_name || 'Marketplace', category_slug: listing.category_slug || '', district: listing.district || listing.city || 'Kendari', condition: listing.condition || 'second', seller_name: listing.seller_name || 'Seller lokal', seller_rating: Number(listing.seller_rating || 0), seller_review_count: Number(listing.seller_review_count || 0), seller_verified: listing.seller_verified || 0 }]); }
function updateCompareTray() { const tray = $('#compare-tray'); if (!tray) return; const items = getCompareItems(); state.compare = items; tray.hidden = !items.length; $('#compare-count').textContent = `${items.length}/3 dipilih`; }
function renderCompare() { const items = getCompareItems(); const dialog = $('#compare-dialog'); const content = $('#compare-content'); if (!dialog || !content) return; if (!items.length) { content.innerHTML = '<p class="empty-inline">Belum ada listing yang dipilih.</p>'; return; } content.innerHTML = `<div class="compare-table">${items.map(item => `<article><div class="compare-icon">${icons[item.category_slug] || '＋'}</div><h3>${esc(item.title)}</h3><strong>${rupiah(item.price)}</strong><dl><div><dt>Kategori</dt><dd>${esc(item.category_name)}</dd></div><div><dt>Lokasi</dt><dd>${esc(item.district)}</dd></div><div><dt>Kondisi</dt><dd>${esc(item.condition === 'new' ? 'Baru' : 'Bekas')}</dd></div><div><dt>Seller</dt><dd>${esc(item.seller_name)} ${Number(item.seller_verified) ? '✓' : ''}</dd></div><div><dt>Rating</dt><dd>★ ${Number(item.seller_rating || 0).toFixed(1)} (${Number(item.seller_review_count || 0)})</dd></div></dl><button class="text-button" data-remove-compare="${Number(item.id)}">Hapus</button></article>`).join('')}</div>`; content.querySelectorAll('[data-remove-compare]').forEach(button => button.onclick = () => { setCompareItems(items.filter(item => Number(item.id) !== Number(button.dataset.removeCompare))); renderCompare(); }); }
function renderRecentlyViewed() { const section = $('#recent-section'); const root = $('#recent-listings'); if (!section || !root) return; state.recent = readLocalArray('sultra-recently-viewed'); section.hidden = !state.recent.length; if (state.recent.length) root.innerHTML = state.recent.map(listingCard).join(''); }
function renderSimilarItems(item) { const similar = [...(window.__listingCache?.values() || [])].filter(row => Number(row.id) !== Number(item.id) && row.category_slug === item.category_slug).slice(0, 3); return similar.length ? `<div class="similar-items"><h3>Mirip dengan ini</h3><div>${similar.map(row => `<button type="button" class="similar-item" data-similar-id="${Number(row.id)}"><span>${icons[row.category_slug] || '＋'}</span><strong>${esc(row.title)}</strong><small>${rupiah(row.price)} · ${esc(row.district || 'Kendari')}</small></button>`).join('')}</div></div>` : ''; }
function openSellerProfile(id) { let dialog = $('#seller-profile-dialog'); if (!dialog) { dialog = document.createElement('dialog'); dialog.id = 'seller-profile-dialog'; dialog.className = 'seller-profile-dialog'; document.body.appendChild(dialog); } dialog.innerHTML = '<div class="seller-profile-modal"><button class="dialog-close" aria-label="Tutup profil seller">×</button><div class="detail-loading">Memuat profil seller…</div></div>'; dialog.showModal(); dialog.querySelector('.dialog-close').onclick = () => dialog.close(); api(`/api/sellers/${Number(id)}`).then(result => { const { seller, listings } = result.data; dialog.querySelector('.seller-profile-modal').innerHTML = `<button class="dialog-close" aria-label="Tutup profil seller">×</button><div class="seller-profile-head"><span class="seller-profile-avatar">${esc(String(seller.name || 'S').slice(0, 1).toUpperCase())}</span><div><span class="eyebrow">${seller.verified ? 'Seller terverifikasi' : 'Seller lokal'}</span><h2>${esc(seller.name)}</h2><p>${esc(seller.district || 'Sulawesi Tenggara')} · ★ ${Number(seller.rating_average || 0).toFixed(1)} (${Number(seller.rating_count || 0)} ulasan)</p></div></div><p>${esc(seller.bio || 'Seller lokal SultraKita. Tanyakan detail produk sebelum transaksi.')}</p><h3>${listings.length} listing aktif</h3><div class="seller-listing-mini">${listings.slice(0, 6).map(row => `<button type="button" data-seller-listing="${Number(row.id)}"><strong>${esc(row.title)}</strong><span>${rupiah(row.price)} · ${esc(row.district || 'Kendari')}</span></button>`).join('') || '<p class="empty-inline">Belum ada listing aktif.</p>'}</div>`; dialog.querySelector('.dialog-close').onclick = () => dialog.close(); dialog.querySelectorAll('[data-seller-listing]').forEach(button => button.onclick = () => { dialog.close(); openDetail(Number(button.dataset.sellerListing)); }); }).catch(error => { dialog.querySelector('.detail-loading').textContent = error.message; }); }
function openDetail(id) { let dialog = $('#listing-detail-dialog'); if (!dialog) { dialog = document.createElement('dialog'); dialog.id = 'listing-detail-dialog'; document.body.appendChild(dialog); } dialog.innerHTML = '<div class="detail-modal"><button class="dialog-close" aria-label="Tutup">×</button><div class="detail-loading">Memuat detail listing…</div></div>'; dialog.showModal(); dialog.querySelector('.dialog-close').onclick = () => dialog.close(); Promise.all([api(`/api/listings/${Number(id)}`), api(`/api/listings/${Number(id)}/images`).catch(() => ({ data: [] })), api(`/api/listings/${Number(id)}/comments`).catch(() => ({ data: [] }))]).then(([detail, images, comments]) => { const item = detail.data; saveRecentlyViewed(item); const gallery = (images.data || []).map(image => `<div class="detail-gallery-image" style="background-image:url('${esc(safeImage(image.file_url))}')"></div>`).join(''); const fallback = `<div class="detail-gallery-image detail-fallback">${icons[item.category_slug] || '＋'}</div>`; const rating = Number(item.seller_rating || 0); const reviewCount = Number(item.seller_review_count || 0); const trustLevel = Number(item.seller_verified) && rating >= 4.7 && reviewCount >= 10 ? 'Gold' : Number(item.seller_verified) ? 'Verified' : 'Basic'; const specEntries = item.specs && typeof item.specs === 'object' ? Object.entries(item.specs).slice(0, 12) : []; const productSpecs = specEntries.length ? `<div class="product-specs"><h3>Spesifikasi</h3><dl>${specEntries.map(([key, value]) => `<div><dt>${esc(key)}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl></div>` : ''; const commentItems = comments.data || []; dialog.querySelector('.detail-modal').innerHTML = `<button class="dialog-close" aria-label="Tutup">×</button><div class="detail-gallery">${gallery || fallback}</div><div class="detail-content"><div class="eyebrow">${esc(item.category_name || 'Listing')} · ${esc(item.district || 'Kendari')}</div><h2>${esc(item.title)}</h2><div class="detail-price">${rupiah(item.price)}</div><p>${esc(item.description || 'Belum ada deskripsi tambahan.')}</p><div class="detail-trust-grid"><span>✓ Garansi SultraKita</span><span>${Number(item.seller_verified) ? `✓ Supplier ${trustLevel}` : '○ Supplier Basic'}</span><span>▣ Perlindungan pembeli</span></div>${productSpecs}<div class="detail-moq"><strong>MOQ</strong><span>${esc(item.moq || '1 unit')} · Tanya harga borongan untuk kebutuhan bisnis.</span></div><div class="detail-seller"><span class="seller-avatar">${esc(String(item.seller_name || 'S').slice(0, 1).toUpperCase())}</span><div><button type="button" class="seller-profile-link" data-seller-id="${Number(item.seller_id || 0)}"><strong>${esc(item.seller_name || 'Seller lokal')}</strong></button><small>★ ${rating.toFixed(1)} (${Number(item.seller_review_count || 0)} ulasan) · ${esc(item.seller_district || item.district || 'Sultra')}</small></div></div><div class="detail-actions"><a class="button button-primary" href="/chat.html?listing=${Number(item.id)}&seller=${Number(item.seller_id || 0)}">Pesan cepat <span>↗</span></a><a class="button button-soft" target="_blank" rel="noopener" href="${window.SultraBridge?.whatsappUrl(item) || '#'}">WhatsApp</a><button class="button button-quiet" data-detail-share-channel="whatsapp">Bagikan WA</button><button class="button button-quiet" data-detail-share-channel="facebook">Facebook</button><button class="button button-quiet" data-detail-share-channel="copy">Salin link</button><button class="button button-quiet" data-detail-compare>⇄ Bandingkan</button><button class="button button-quiet" data-detail-bulk>Tanya borongan</button><button class="button button-quiet" data-detail-report>Laporkan</button></div><div class="report-panel" id="detail-report-panel" hidden><label>Alasan laporan<select id="detail-report-reason"><option>Penipuan atau indikasi scam</option><option>Barang/jasa ilegal</option><option>Informasi menyesatkan</option><option>Konten tidak pantas</option></select></label><button class="button button-soft" data-submit-report>Kirim laporan</button><p class="form-message" id="detail-report-message" role="status"></p></div>${window.SultraBridge?.safeZoneLinks() || ''}${renderSimilarItems(item)}<div class="detail-comments"><div class="comments-head"><h3>Diskusi (${commentItems.length})</h3><span>Bagikan pengalaman dengan aman</span></div><div class="comment-list">${commentItems.map(comment => `<article><strong>${esc(comment.author_name)}</strong><p>${esc(comment.body)}</p><small>${esc(String(comment.created_at || '').slice(0, 10))}</small></article>`).join('') || '<p class="empty-inline">Belum ada komentar. Jadilah yang pertama bertanya dengan sopan.</p>'}</div><form id="detail-comment-form"><label class="sr-only" for="detail-comment-body">Komentar</label><textarea id="detail-comment-body" maxlength="1000" minlength="3" placeholder="Tanyakan detail produk…" required></textarea><button class="button button-soft" type="submit">Kirim komentar</button><p class="form-message" id="detail-comment-message" role="status"></p></form></div></div>`; dialog.querySelector('.dialog-close').onclick = () => dialog.close(); dialog.querySelector('[data-seller-id]')?.addEventListener('click', () => openSellerProfile(Number(item.seller_id))); dialog.querySelector('[data-detail-compare]').onclick = () => { toggleCompare(item); updateCompareTray(); }; dialog.querySelector('[data-detail-bulk]').onclick = () => { const rfq = $('#rfq-dialog'); const form = $('#rfq-form'); if (rfq && form) { form.elements.title.value = `Kebutuhan borongan: ${item.title}`; form.elements.description.value = `Saya tertarik dengan ${item.title}. Mohon info harga grosir, MOQ, stok, dan estimasi pengiriman.`; rfq.showModal(); } }; dialog.querySelector('[data-detail-report]').onclick = () => { const panel = dialog.querySelector('#detail-report-panel'); panel.hidden = !panel.hidden; }; dialog.querySelector('[data-submit-report]').onclick = async () => { const message = dialog.querySelector('#detail-report-message'); const token = authToken(); if (!token) { message.textContent = 'Login diperlukan untuk mengirim laporan.'; return; } try { await api('/api/reports', { method: 'POST', headers: { 'content-type': 'application/json', authorization: `Bearer ${token}` }, body: JSON.stringify({ listing_id: Number(item.id), reporter_name: 'Pengguna SultraKita', reason: dialog.querySelector('#detail-report-reason').value }) }); message.textContent = 'Laporan diterima untuk moderasi.'; } catch (error) { message.textContent = error.message; } }; dialog.querySelectorAll('[data-detail-share-channel]').forEach(button => button.onclick = () => shareChannel(button.dataset.detailShareChannel, item)); dialog.querySelectorAll('[data-similar-id]').forEach(button => button.onclick = () => openDetail(Number(button.dataset.similarId))); dialog.querySelector('#detail-comment-form').onsubmit = async event => { event.preventDefault(); const message = dialog.querySelector('#detail-comment-message'); const token = authToken(); if (!token) { message.textContent = 'Login diperlukan untuk ikut berdiskusi.'; return; } try { await api('/api/comments', { method: 'POST', headers: { 'content-type': 'application/json', authorization: `Bearer ${token}` }, body: JSON.stringify({ listing_id: Number(item.id), author_name: 'Pengguna SultraKita', body: dialog.querySelector('#detail-comment-body').value }) }); message.textContent = 'Komentar terkirim.'; } catch (error) { message.textContent = error.message; } }; track('listing_view', item.id); }).catch(error => { dialog.querySelector('.detail-loading').textContent = error.message; }); }

function bindListingEvents() { $('#listings').addEventListener('click', event => { const action = event.target.closest('[data-action]'); const card = event.target.closest('[data-open-listing]'); if (action?.dataset.action === 'favorite') { event.stopPropagation(); toggleFavorite(Number(action.dataset.id), action); return; } if (action?.dataset.action === 'compare') { event.stopPropagation(); const listing = window.__listingCache?.get(Number(action.dataset.id)); if (listing) { toggleCompare(listing); updateCompareTray(); } return; } if (action?.dataset.action === 'react') { event.stopPropagation(); toggleReaction(Number(action.dataset.id), action); return; } if (action?.dataset.action === 'share') { event.stopPropagation(); shareListing(action.dataset.title); track('listing_share', Number(card?.dataset.openListing)); return; } if (action?.dataset.action === 'fb-copy' || action?.dataset.action === 'flyer') { event.stopPropagation(); const listing = window.__listingCache?.get(Number(card?.dataset.openListing)); if (!listing) { openDetail(Number(card?.dataset.openListing)); return; } if (action.dataset.action === 'fb-copy') navigator.clipboard?.writeText(window.SultraBridge.fbText(listing)).then(() => toast('Teks listing siap ditempel ke Facebook Marketplace.')).catch(() => toast('Clipboard tidak tersedia; buka detail listing untuk menyalin manual.')); else window.SultraBridge.downloadFlyer(listing); return; } if (action?.dataset.action === 'ask') { event.stopPropagation(); if (card) openDetail(Number(card.dataset.openListing)); return; } if (card) openDetail(Number(card.dataset.openListing)); }); $('#listings').addEventListener('keydown', event => { if ((event.key === 'Enter' || event.key === ' ') && event.target.closest('[data-open-listing]')) { event.preventDefault(); openDetail(Number(event.target.closest('[data-open-listing]').dataset.openListing)); } }); }

function applyTheme(dark) { document.body.classList.toggle('dark', dark); document.documentElement.classList.toggle('theme-dark-preload', dark); localStorage.setItem('sultra-dark', String(dark)); document.querySelector('meta[name="theme-color"]')?.setAttribute('content', dark ? '#10231f' : '#0d5c4b'); const button = $('#theme-toggle'); if (button) { button.textContent = dark ? '☀' : '◐'; button.setAttribute('aria-label', dark ? 'Aktifkan mode terang' : 'Aktifkan mode gelap'); button.setAttribute('aria-pressed', String(dark)); } }
function setupTheme() { const stored = localStorage.getItem('sultra-dark'); const dark = stored === 'true' || (stored === null && window.matchMedia?.('(prefers-color-scheme: dark)').matches); applyTheme(dark); $('#theme-toggle').onclick = () => applyTheme(!document.body.classList.contains('dark')); }
function openSellDialog() { const dialog = $('#sell-dialog'); if (dialog && !dialog.open) dialog.showModal(); }

async function compressImage(file) { if (!/^image\/(jpeg|png|webp)$/.test(file.type) || file.size < 350 * 1024) return file; return new Promise(resolve => { const image = new Image(); const url = URL.createObjectURL(file); image.onload = () => { const scale = Math.min(1, 1600 / Math.max(image.naturalWidth, image.naturalHeight)); const canvas = document.createElement('canvas'); canvas.width = Math.max(1, Math.round(image.naturalWidth * scale)); canvas.height = Math.max(1, Math.round(image.naturalHeight * scale)); canvas.getContext('2d').drawImage(image, 0, 0, canvas.width, canvas.height); canvas.toBlob(blob => { URL.revokeObjectURL(url); resolve(blob ? new File([blob], file.name.replace(/\.[^.]+$/, '.jpg'), { type: 'image/jpeg' }) : file); }, 'image/jpeg', 0.82); }; image.onerror = () => { URL.revokeObjectURL(url); resolve(file); }; image.src = url; }); }

async function uploadListingImages(listingId, files) { const optimizedFiles = await Promise.all(files.map(compressImage)); files = optimizedFiles; const headers = { authorization: `Bearer ${state.sellerSession.token}`, 'content-type': 'application/json' }; try { const presigned = await api('/api/uploads/presign', { method: 'POST', headers, body: JSON.stringify({ listingId, files: files.map(file => ({ name: file.name, type: file.type, size: file.size })) }) }); const uploads = presigned.data || []; await Promise.all(uploads.map((item, index) => fetch(item.uploadUrl, { method: 'PUT', headers: { 'content-type': files[index].type }, body: files[index] }).then(response => { if (!response.ok) throw new Error('Upload foto ke storage gagal.'); }))); await api('/api/uploads/commit', { method: 'POST', headers, body: JSON.stringify({ listingId, uploads }) }); return; } catch (error) { if (error.code !== 'STORAGE_UNAVAILABLE') throw error; const data = new FormData(); files.forEach(file => data.append('images', file)); await api(`/api/listings/${listingId}/images`, { method: 'POST', headers: { authorization: `Bearer ${state.sellerSession.token}` }, body: data }); } }

function setupOtpChannel(form) { const radios = [...form.querySelectorAll('input[name="otp_channel"]')]; const sync = () => { const channel = form.querySelector('input[name="otp_channel"]:checked')?.value || 'whatsapp'; const phoneField = form.querySelector('#otp-phone-field'); const emailField = form.querySelector('#otp-email-field'); const phone = form.elements.phone; const email = form.elements.email; const button = form.querySelector('#request-otp'); if (!phoneField || !emailField || !phone || !email || !button) return; phoneField.hidden = channel !== 'whatsapp'; emailField.hidden = channel !== 'email'; phone.disabled = channel !== 'whatsapp'; email.disabled = channel !== 'email'; phone.required = channel === 'whatsapp'; email.required = channel === 'email'; button.textContent = channel === 'email' ? 'Kirim OTP Email' : 'Kirim OTP WhatsApp'; }; radios.forEach(radio => { radio.addEventListener('change', sync); radio.addEventListener('input', sync); }); sync(); return () => form.querySelector('input[name="otp_channel"]:checked')?.value || 'whatsapp'; }
function setupSellerForm() {
  const form = $('#listing-form'); if (!form) return;
  const dialog = $('#sell-dialog');
  const getOtpChannel = setupOtpChannel(form);
  const draftKey = 'sultra-seller-onboarding-draft';
  let currentStep = 1;
  let draftLoaded = false;
  let previewUrls = [];
  let progress = { current_step: 1, account_data: {}, store_data: {}, product_data: {}, completed_steps: [] };
  try { state.sellerSession = JSON.parse(sessionStorage.getItem('sultra-seller-session') || 'null'); } catch (error) { console.error('[seller-session]', error); state.sellerSession = null; }
  const token = () => state.sellerSession?.token || '';
  const headers = () => ({ 'content-type': 'application/json', ...(token() ? { authorization: `Bearer ${token()}` } : {}) });
  const setMessage = (message, tone = '') => { const element = $('#form-message'); if (element) { element.textContent = message; element.dataset.tone = tone; } };
  const readDraft = () => { try { const value = JSON.parse(localStorage.getItem(draftKey) || '{}'); return value && typeof value === 'object' ? value : {}; } catch { return {}; } };
  const collectDraft = () => ({ current_step: currentStep, account_data: { email: form.elements.email.value.trim(), phone: form.elements.phone.value.trim(), name: form.elements.seller_name.value.trim() }, store_data: { store_name: form.elements.store_name.value.trim(), store_category: form.elements.store_category.value, store_description: form.elements.store_description.value.trim(), district: form.elements.district.value }, product_data: { title: form.elements.title.value.trim(), description: form.elements.description.value.trim(), price: form.elements.price.value, category_id: form.elements.category_id.value, condition: form.elements.condition.value, shipping_methods: [...form.elements.shipping_methods.selectedOptions].map(option => option.value), photo_names: [...(form.elements.images.files || [])].map(file => file.name) }, completed_steps: progress.completed_steps || [] });
  const persistProgress = async (nextStep = currentStep, completed = progress.completed_steps || []) => { currentStep = nextStep; progress = { ...collectDraft(), current_step: nextStep, completed_steps: [...new Set(completed)] }; localStorage.setItem(draftKey, JSON.stringify(progress)); if (!token()) return; try { const result = await api('/api/seller/onboarding', { method: 'PATCH', headers: headers(), body: JSON.stringify(progress) }); progress = { ...progress, ...result.data }; } catch (error) { console.warn('[onboarding-progress]', error.message); } };
  const fillDraft = data => { const account = data.account_data || {}; const store = data.store_data || {}; const product = data.product_data || {}; if (account.email) form.elements.email.value = account.email; if (account.phone) form.elements.phone.value = account.phone; if (account.name) form.elements.seller_name.value = account.name; if (store.store_name) form.elements.store_name.value = store.store_name; if (store.store_category) form.elements.store_category.value = store.store_category; if (store.store_description) form.elements.store_description.value = store.store_description; if (store.district) form.elements.district.value = store.district; if (product.title) form.elements.title.value = product.title; if (product.description) form.elements.description.value = product.description; if (product.price) form.elements.price.value = product.price; if (product.category_id) form.elements.category_id.value = product.category_id; if (product.condition) form.elements.condition.value = product.condition; const methods = Array.isArray(product.shipping_methods) ? product.shipping_methods : []; [...form.elements.shipping_methods.options].forEach(option => { option.selected = methods.includes(option.value); }); currentStep = Math.min(4, Math.max(1, Number(data.current_step || 1))); progress = { ...progress, ...data }; };
  const updateCounter = () => { const field = form.elements.store_description; const counter = $('#store-description-counter'); if (counter) counter.textContent = `${field.value.length}/160`; };
  const clearPreviewUrls = () => { previewUrls.forEach(url => URL.revokeObjectURL(url)); previewUrls = []; };
  const renderPhotoPreview = () => { const preview = $('#onboarding-photo-preview'); if (!preview) return; clearPreviewUrls(); const files = [...(form.elements.images.files || [])].slice(0, 5); preview.innerHTML = files.map(file => { const url = URL.createObjectURL(file); previewUrls.push(url); return `<div class="onboarding-photo-thumb"><img src="${esc(url)}" alt="Pratinjau ${esc(file.name)}"><span>${esc(file.name)}</span></div>`; }).join(''); };
  const showStep = step => { currentStep = Math.min(4, Math.max(1, step)); form.querySelectorAll('[data-onboarding-step]').forEach(section => { const active = Number(section.dataset.onboardingStep) === currentStep; section.hidden = !active; section.classList.toggle('active', active); }); form.querySelectorAll('[data-step-dot]').forEach(dot => { const number = Number(dot.dataset.stepDot); dot.classList.toggle('active', number === currentStep); dot.classList.toggle('complete', number < currentStep); dot.setAttribute('aria-current', number === currentStep ? 'step' : 'false'); }); const fill = $('#onboarding-progress-fill'); if (fill) fill.style.width = `${((currentStep - 1) / 3) * 100}%`; const progressbar = form.querySelector('[role=progressbar]'); if (progressbar) progressbar.setAttribute('aria-valuenow', String(currentStep)); updateCounter(); if (currentStep === 4) renderSummary(); };
  const renderSummary = () => { const summary = $('#onboarding-summary'); if (!summary) return; const title = form.elements.title.value.trim() || 'Produk pertama'; const category = form.elements.category_id.selectedOptions[0]?.textContent || 'Belum dipilih'; summary.innerHTML = `<div class="summary-product"><div class="summary-product-art">${form.elements.images.files?.length ? '▣' : '＋'}</div><div><strong>${esc(title)}</strong><span>${esc(category)} · ${esc(form.elements.district.value || 'Kendari')}</span><b>${rupiah(form.elements.price.value)}</b></div></div><dl><div><dt>Toko</dt><dd>${esc(form.elements.store_name.value.trim() || 'Belum diisi')}</dd></div><div><dt>Kondisi</dt><dd>${form.elements.condition.value === 'second' ? 'Bekas' : 'Baru'}</dd></div><div><dt>Foto</dt><dd>${form.elements.images.files?.length || 0} foto dipilih</dd></div></dl>`; };
  const validateStep = step => { let firstInvalid = null; const fields = step === 1 ? [form.elements.seller_name, getOtpChannel() === 'email' ? form.elements.email : form.elements.phone, ...(state.sellerSession ? [] : [form.elements.otp]), ...(form.elements.policy_consent ? [form.elements.policy_consent] : [])] : step === 2 ? [form.elements.store_name, form.elements.store_category, form.elements.district] : step === 3 ? [form.elements.title, form.elements.description, form.elements.price, form.elements.category_id] : []; fields.forEach(field => { if (!field.checkValidity() && !firstInvalid) firstInvalid = field; }); if (step === 3 && !form.elements.images.files?.length) { setMessage('Tambahkan minimal satu foto produk agar listing lebih mudah ditemukan.', 'error'); return false; } if (firstInvalid) { firstInvalid.focus(); firstInvalid.classList.add('field-shake'); setTimeout(() => firstInvalid.classList.remove('field-shake'), 360); setMessage('Lengkapi field yang ditandai sebelum lanjut.', 'error'); return false; } return true; };
  const loadProgress = async () => { if (draftLoaded) return; draftLoaded = true; const local = readDraft(); if (local.account_data || local.store_data || local.product_data) fillDraft(local); if (!token()) { showStep(currentStep); return; } try { const result = await api('/api/seller/onboarding', { headers: { authorization: token() } }); fillDraft(result.data); } catch (error) { console.warn('[onboarding-load]', error.message); } showStep(currentStep); };
  const nextStep = async step => { if (!validateStep(step)) return; if (step === 1 && !state.sellerSession) { const channel = getOtpChannel(); const phone = form.elements.phone.value.trim(); const email = form.elements.email.value.trim(); try { const verified = await api('/api/auth/verify-otp', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ channel, phone: channel === 'whatsapp' ? phone : undefined, email: channel === 'email' ? email : undefined, code: form.elements.otp.value.trim(), name: form.elements.seller_name.value.trim(), role: 'seller', district: form.elements.district.value || 'Kendari' }) }); state.sellerSession = verified.data; sessionStorage.setItem('sultra-seller-session', JSON.stringify(state.sellerSession)); } catch (error) { setMessage(error.message, 'error'); return; } } await persistProgress(step + 1, [...(progress.completed_steps || []), step]); showStep(step + 1); };
  const requestOtp = async () => { const channel = getOtpChannel(); const phone = form.elements.phone.value.trim(); const email = form.elements.email.value.trim(); if (channel === 'whatsapp' && !/^08\d{8,13}$/.test(phone)) { setMessage('Masukkan nomor WhatsApp yang valid.', 'error'); return; } if (channel === 'email' && !/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) { setMessage('Masukkan email yang valid.', 'error'); return; } const button = form.querySelector('#request-otp'); button.disabled = true; try { const result = await api('/api/auth/request-otp', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ channel, phone: channel === 'whatsapp' ? phone : undefined, email: channel === 'email' ? email : undefined }) }); setMessage(result.data?.dev_code ? `OTP demo: ${result.data.dev_code}` : `Kode OTP ${channel === 'email' ? 'email' : 'WhatsApp'} telah dikirim.`); } catch (error) { setMessage(error.message, 'error'); } finally { button.disabled = false; } };
  const suggest = async () => { const button = $('#onboarding-ai-suggest'); const status = $('#onboarding-ai-status'); const files = [...(form.elements.images.files || [])].slice(0, 5); if (!files.length) { setMessage('Pilih foto produk dulu agar asisten dapat membantu.', 'error'); return; } if (!token()) { setMessage('Selesaikan verifikasi akun terlebih dahulu.', 'error'); showStep(1); return; } button.disabled = true; status.textContent = 'Menyiapkan draft…'; status.classList.add('is-loading'); try { const result = await api('/api/seller/onboarding/suggest', { method: 'POST', headers: headers(), body: JSON.stringify({ photo_names: files.map(file => file.name), title: form.elements.title.value, description: form.elements.description.value, price: form.elements.price.value, category_id: form.elements.category_id.value, district: form.elements.district.value }) }); const suggestion = result.data || {}; form.elements.title.value = suggestion.title || form.elements.title.value; form.elements.description.value = suggestion.description || form.elements.description.value; if (suggestion.price) form.elements.price.value = suggestion.price; if (suggestion.category_id) form.elements.category_id.value = suggestion.category_id; status.textContent = suggestion.source === 'openai' ? 'Draft AI siap ditinjau.' : 'Draft bantuan lokal siap ditinjau.'; } catch (error) { status.textContent = ''; setMessage(error.message, 'error'); } finally { status.classList.remove('is-loading'); button.disabled = false; } };
  const finish = async () => { if (window.SultraPolicy && !window.SultraPolicy.hasConsent()) { window.SultraPolicy.require('menerbitkan listing', finish); return; } if (!validateStep(3) || state.listingBusy) return; state.listingBusy = true; const finishButton = $('#onboarding-finish'); finishButton.disabled = true; setMessage('Menyimpan toko dan menerbitkan listing…'); try { const data = collectDraft(); const created = await api('/api/seller/onboarding/finalize', { method: 'POST', headers: headers(), body: JSON.stringify({ store_data: data.store_data, product_data: data.product_data }) }); const files = [...(form.elements.images.files || [])]; if (files.length) await uploadListingImages(created.data.listing.id, files); localStorage.removeItem(draftKey); progress = { ...progress, current_step: 4, status: 'completed' }; showStep(4); setMessage('Listing berhasil dipublikasikan.'); toast('Listing pertama kamu sudah tayang.'); setTimeout(() => { dialog.close(); form.reset(); showStep(1); loadStats(); loadListings(); }, 900); } catch (error) { setMessage(error.message, 'error'); } finally { state.listingBusy = false; finishButton.disabled = false; } };
  const open = () => { const proceed = () => { loadProgress(); if (!dialog.open) dialog.showModal(); }; if (window.SultraPolicy) window.SultraPolicy.require('memasang listing', proceed); else proceed(); };
  $('#open-sell').onclick = open; $('#hero-sell').onclick = open; $('#mobile-sell').onclick = open; $('#show-guide').onclick = () => toast('Tip: gunakan foto terang, judul spesifik, dan tulis kondisi apa adanya.');
  form.querySelector('.dialog-close').onclick = event => { event.preventDefault(); dialog.close(); }; form.querySelector('#request-otp').onclick = requestOtp; form.querySelectorAll('[data-onboarding-next]').forEach(button => button.onclick = () => nextStep(Number(button.dataset.onboardingNext))); form.querySelectorAll('[data-onboarding-back]').forEach(button => button.onclick = () => { setMessage(''); showStep(Number(button.dataset.onboardingBack) - 1); }); form.querySelectorAll('[data-step-dot]').forEach(dot => dot.onclick = () => { const step = Number(dot.dataset.stepDot); if (step < currentStep) showStep(step); }); form.elements.images.addEventListener('change', renderPhotoPreview); form.elements.store_description.addEventListener('input', updateCounter); $('#onboarding-ai-suggest').onclick = suggest; $('#onboarding-finish').onclick = finish; $('#onboarding-add-more').onclick = () => { form.elements.title.value = ''; form.elements.description.value = ''; form.elements.price.value = ''; form.elements.images.value = ''; renderPhotoPreview(); showStep(3); }; form.addEventListener('submit', event => event.preventDefault()); showStep(1);
}

function setupDiscovery() { $('#hero-explore').onclick = () => $('#jelajah').scrollIntoView({ behavior: 'smooth' }); $('#search-button').onclick = () => { $('#suggestions').hidden = true; track('search'); loadListings(); }; $('#search').addEventListener('keydown', event => { if (event.key === 'Enter') { $('#suggestions').hidden = true; track('search'); loadListings(); } }); $('#search').addEventListener('input', () => { clearTimeout(state.searchTimer); clearTimeout(state.suggestionTimer); state.searchTimer = setTimeout(() => loadListings(), 360); state.suggestionTimer = setTimeout(renderSuggestions, 180); }); $('#search').addEventListener('focus', renderSuggestions); document.addEventListener('click', event => { if (!event.target.closest('.top-search')) $('#suggestions').hidden = true; }); $('#suggestions').addEventListener('click', event => { const suggestion = event.target.closest('[data-suggestion]'); if (!suggestion) return; $('#search').value = suggestion.dataset.suggestion; $('#suggestions').hidden = true; loadListings(); }); $('#district').addEventListener('change', () => { syncDiscoveryUrl(); loadListings(); }); $('#sort').addEventListener('change', () => { syncDiscoveryUrl(); loadListings(); }); const observer = 'IntersectionObserver' in window ? new IntersectionObserver(entries => { if (entries[0].isIntersecting && state.page < state.totalPages) { state.page += 1; loadListings({ reset: false }); } }, { rootMargin: '500px' }) : null; if (observer) observer.observe($('#load-more')); document.addEventListener('click', event => { const category = event.target.closest('[data-category]'); if (category) { state.category = category.dataset.category; renderCategories(); syncDiscoveryUrl(); loadListings(); $('#jelajah').scrollIntoView({ behavior: 'smooth' }); } }); $('#clear-filter').onclick = () => { state.category = ''; renderCategories(); syncDiscoveryUrl(); loadListings(); }; $('.filter-chip').onclick = () => { state.category = ''; renderCategories(); syncDiscoveryUrl(); loadListings(); }; window.addEventListener('popstate', () => { const url = new URL(location.href); $('#search').value = url.searchParams.get('q') || ''; $('#district').value = url.searchParams.get('district') || ''; $('#sort').value = url.searchParams.get('sort') || 'newest'; state.category = url.searchParams.get('category') || ''; renderCategories(); loadListings(); }); $('#load-more').onclick = () => { state.page += 1; loadListings({ reset: false }); }; }

function setupLocationPicker(regions) { const pill = $('#location-pill'); if (!pill || $('#location-dialog')) return; const dialog = document.createElement('dialog'); dialog.id = 'location-dialog'; dialog.className = 'location-dialog'; const grouped = regions.map(region => `<optgroup label="${esc(region.name)}">${region.districts.map(district => `<option value="${esc(district)}">${esc(district)}</option>`).join('')}</optgroup>`).join(''); dialog.innerHTML = `<form method="dialog" class="location-picker-modal"><div class="location-picker-head"><div><span class="eyebrow">Lokasi pencarian</span><h2>Pilih wilayahmu</h2><p>Temukan listing yang lebih dekat dengan aktivitasmu.</p></div><button class="dialog-close" value="cancel" aria-label="Tutup">×</button></div><label for="location-select">Wilayah<select id="location-select"><option value="">Semua wilayah Sultra</option>${grouped}</select></label><div class="location-picker-actions"><button class="button button-quiet" value="clear">Reset</button><button class="button button-primary" value="apply">Terapkan wilayah <span>→</span></button></div></form>`; document.body.appendChild(dialog); const select = $('#location-select'); const label = $('#location-label'); const setLabel = value => { label.textContent = value ? `${value}, Sultra` : 'Kendari, Sultra'; }; pill.onclick = () => { select.value = $('#district').value || ''; dialog.showModal(); }; dialog.querySelector('form').addEventListener('submit', event => { const action = event.submitter?.value; if (action === 'apply' || action === 'clear') { const value = action === 'clear' ? '' : select.value; $('#district').value = value; setLabel(value); syncDiscoveryUrl(); loadListings(); track('location_filter'); } }); }

async function setupLocations() { let regions = fallbackTaxonomy.REGIONS; try { const result = await api('/api/locations'); regions = result.data?.regions?.length ? result.data.regions : regions; if (result.meta?.source === 'fallback') toast('Daftar wilayah offline dipakai sementara.', 'warn'); } catch (error) { console.error('[locations]', error); toast('Daftar wilayah offline dipakai sementara.', 'warn'); } state.regions = regions; const allDistricts = [...new Set(regions.flatMap(region => region.districts))]; $('#district').innerHTML = '<option value="">Semua wilayah</option>' + allDistricts.map(district => `<option value="${esc(district)}">${esc(district)}</option>`).join(''); const regionSelect = $('#form-region'); const districtSelect = $('#form-district'); if (!districtSelect) { setupLocationPicker(regions); return; } const renderDistricts = () => { const region = regionSelect ? (regions.find(item => item.slug === regionSelect.value) || regions[0]) : regions[0]; districtSelect.innerHTML = region.districts.map(district => `<option value="${esc(district)}">${esc(district)}</option>`).join(''); }; if (!regionSelect) { renderDistricts(); setupLocationPicker(regions); return; } regionSelect.innerHTML = regions.map(region => `<option value="${esc(region.slug)}">${esc(region.name)}</option>`).join(''); regionSelect.addEventListener('change', renderDistricts); renderDistricts(); setupLocationPicker(regions); }

async function loadExternalListings() { try { const result = await api('/api/external-listings'); const rows = result.data || []; const section = $('#partner-picks'); if (!rows.length) { section.hidden = true; return; } section.hidden = false; $('#partner-summary').textContent = `${rows.length} listing dari ${result.meta?.configured_feeds || 0} feed resmi · sumber eksternal`; $('#partner-listings').innerHTML = rows.slice(0, 8).map(row => `<article class="partner-card"><div><span class="partner-source">${esc(row.source_label || row.source)}</span><h3>${esc(row.title)}</h3><p>${esc(row.category || 'Marketplace')} · ${esc(row.city || 'Kendari')} ${row.price ? `· ${rupiah(row.price)}` : ''}</p></div><div class="partner-card-bottom"><small>Diamati ${esc(String(row.observed_at || '').slice(0, 10))}</small><a class="partner-link" href="${esc(row.url)}" target="_blank" rel="noopener noreferrer">Buka sumber ↗</a></div></article>`).join(''); } catch (error) { console.error('[external-listings]', error); $('#partner-picks').hidden = true; } }

function setupDonation() {
  const button = $('#donation-cta'); if (!button) return; const dialog = document.createElement('dialog'); dialog.id = 'donation-dialog'; dialog.innerHTML = `<form method="dialog" class="donation-modal" id="donation-form"><div class="modal-head"><div><div class="eyebrow">Dukung SultraKita</div><h2 id="donation-title">Bantu platform lokal terus tumbuh</h2><p class="dialog-help" id="donation-description">Memuat kampanye aktif…</p></div><button class="dialog-close" value="cancel" aria-label="Tutup">×</button></div><div class="donation-progress"><div class="donation-progress-meta"><span id="donation-raised">Terkumpul —</span><span id="donation-target">Target —</span></div><div class="donation-progress-track"><span id="donation-progress-bar"></span></div><small id="donation-supporters"></small></div><fieldset><legend>Pilih nominal donasi</legend><div class="donation-presets">${[25000,50000,100000,250000].map(amount => `<button type="button" class="donation-preset" data-amount="${amount}">${rupiah(amount)}</button>`).join('')}</div></fieldset><label>Metode pembayaran<select id="donation-payment-method" name="payment_method"><option value="qris">QRIS</option><option value="virtual_account">Virtual Account</option></select></label><label>Nominal lainnya (Rp)<input id="donation-amount" name="amount" type="number" min="10000" max="100000000" step="1000" value="50000" required></label><label>Nama tampilan (opsional)<input id="donation-name" name="name" maxlength="100" placeholder="Hamba Allah"></label><button class="button button-primary full" id="donation-submit" type="submit">Dukung sekarang <span id="donation-submit-amount">Rp 50.000</span></button><p class="form-message" id="donation-message" role="status"></p></form>`; document.body.appendChild(dialog); let campaignId = 1; const amount = dialog.querySelector('#donation-amount'); const message = dialog.querySelector('#donation-message'); const refresh = () => { dialog.querySelector('#donation-submit-amount').textContent = rupiah(amount.value); }; amount.oninput = refresh; dialog.querySelectorAll('.donation-preset').forEach(preset => preset.onclick = () => { amount.value = preset.dataset.amount; refresh(); dialog.querySelectorAll('.donation-preset').forEach(item => item.classList.toggle('selected', item === preset)); }); const load = async () => { const result = await api(`/api/donation/stats?campaign_id=${campaignId}`); const { campaign, supporters } = result.data; dialog.querySelector('#donation-title').textContent = campaign.title; dialog.querySelector('#donation-description').textContent = campaign.description || 'Dukungan Anda membantu biaya operasional SultraKita.'; dialog.querySelector('#donation-raised').textContent = `Terkumpul ${rupiah(campaign.current_amount)}`; dialog.querySelector('#donation-target').textContent = `Target ${rupiah(campaign.target_amount)}`; dialog.querySelector('#donation-progress-bar').style.width = `${campaign.progress_percent}%`; dialog.querySelector('#donation-supporters').textContent = `${supporters} donatur terverifikasi`; }; button.onclick = async () => { if (window.SultraPolicy && !window.SultraPolicy.hasConsent()) { window.SultraPolicy.require('mendukung proyek melalui pembayaran', () => button.click()); return; } dialog.showModal(); message.textContent = 'Memuat kampanye…'; try { await load(); message.textContent = ''; } catch (error) { message.textContent = error.message; } }; dialog.querySelector('#donation-form').onsubmit = async event => { event.preventDefault(); const submit = dialog.querySelector('#donation-submit'); const amountValue = Number(amount.value); if (!Number.isSafeInteger(amountValue) || amountValue < 10000) { message.textContent = 'Minimal donasi Rp10.000.'; return; } submit.disabled = true; message.textContent = 'Mengalihkan ke pembayaran aman…'; try { const result = await api('/api/donations', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ campaign_id: campaignId, amount: amountValue, name: dialog.querySelector('#donation-name').value || 'Hamba Allah', payment_method: dialog.querySelector('#donation-payment-method').value }) }); localStorage.setItem('sultrakita:last-donation', result.data.transaction_id); if (result.data.payment_url) location.assign(result.data.payment_url); else { message.textContent = result.data.message || 'Donasi tercatat.'; await load(); } } catch (error) { message.textContent = error.message; } finally { submit.disabled = false; } }; }

function setupAdminDashboard() { const root = $('#admin-analytics'); if (!root) return; const value = id => $(id)?.value.trim() || ''; const headers = () => ({ authorization: `Bearer ${value('#admin-session-token')}`, 'x-admin-token': value('#admin-token') }); const load = async () => { const result = await api(`/api/admin/donations/analytics?days=${value('#admin-analytics-days') || 30}`, { headers: headers() }); const { totals, daily } = result.data; $('#admin-attempts').textContent = totals.attempts; $('#admin-successful').textContent = totals.successful; $('#admin-success-rate').textContent = `${totals.success_rate}%`; $('#admin-net-amount').textContent = rupiah(totals.net_amount); $('#admin-daily-chart').innerHTML = daily.map(row => `<div class="analytics-bar-row"><span>${row.date}</span><div><i style="width:${Math.min(100, Number(row.attempts) * 10)}%"></i></div><strong>${row.successful}/${row.attempts} · ${rupiah(row.net_amount)}</strong></div>`).join('') || '<p>Belum ada transaksi.</p>'; }; $('#admin-analytics-load')?.addEventListener('click', () => load().catch(error => { $('#admin-daily-chart').textContent = error.message; })); }

async function loadExternalJobs() { try { const result = await api('/api/external-jobs'); const rows = result.data || []; const section = $('#job-board'); if (!rows.length) { section.hidden = true; return; } section.hidden = false; $('#job-summary').textContent = `${rows.length} kartu lowongan · ${result.meta?.imported_urls || result.meta?.configured_feeds || 0} sumber · filter Kendari/Sultra`; $('#job-listings').innerHTML = rows.slice(0, 8).map(row => `<article class="partner-card job-card">${row.image_url ? `<img class="job-card-image" src="${esc(row.image_url)}" alt="Thumbnail dari ${esc(row.source_label || row.source)}" loading="lazy" decoding="async" width="400" height="225" referrerpolicy="no-referrer">` : `<div class="job-card-image job-card-image-fallback">💼</div>`}<div><span class="partner-source">${esc(row.source_label || row.source)}</span><h3>${esc(row.title)}</h3><p>${esc(row.company || 'Perusahaan lokal')} · ${esc(row.city || 'Sulawesi Tenggara')}</p><p>${esc(row.employment_type || 'Tipe kerja belum disebutkan')} ${row.salary_text ? `· ${esc(row.salary_text)}` : ''}</p><p class="job-card-description">${esc(row.description || 'Buka sumber asli untuk melihat persyaratan dan cara melamar.')}</p></div><div class="partner-card-bottom"><small>Diamati ${esc(String(row.observed_at || '').slice(0, 10))}</small><a class="partner-link" href="${esc(row.url)}" target="_blank" rel="noopener noreferrer">Lihat sumber ↗</a></div></article>`).join(''); } catch (error) { console.error('[external-jobs]', error); $('#job-board').hidden = true; } }

function setupSidebarNavigation() { document.querySelector('[data-donation-nav]')?.addEventListener('click', event => { event.preventDefault(); $('#donation-cta')?.click(); }); }

async function loadTrending() { try { const result = await api('/api/listings?sort=popular&limit=4'); const rows = result.data || []; const section = $('#trending-section'); if (!section || !rows.length) return; section.hidden = false; $('#trending-listings').innerHTML = rows.map(listingCard).join(''); } catch (error) { console.warn('[trending]', error.message); } }

async function setupRealtime() { try { if (window.SultraLiveFeed?.start) await window.SultraLiveFeed.start(); } catch (error) { console.warn('[realtime]', error.message); } }

function setupPhase3() { const url = new URL(location.href); state.radius = url.searchParams.get('radius') || localStorage.getItem('sultra-radius') || '10'; state.minPrice = url.searchParams.get('min_price') || ''; state.maxPrice = url.searchParams.get('max_price') || ''; state.view = localStorage.getItem('sultra-view') || 'grid'; const radius = $('#radius'); const minPrice = $('#min-price'); const maxPrice = $('#max-price'); if (radius) radius.value = state.radius; if (minPrice) minPrice.value = state.minPrice; if (maxPrice) maxPrice.value = state.maxPrice; const applyFilters = () => { state.radius = radius?.value || '10'; state.minPrice = minPrice?.value || ''; state.maxPrice = maxPrice?.value || ''; localStorage.setItem('sultra-radius', state.radius); syncDiscoveryUrl(); loadListings(); }; radius?.addEventListener('change', applyFilters); minPrice?.addEventListener('change', applyFilters); maxPrice?.addEventListener('change', applyFilters); document.querySelectorAll('[data-view]').forEach(button => { button.classList.toggle('active', button.dataset.view === state.view); button.addEventListener('click', () => { state.view = button.dataset.view || 'grid'; localStorage.setItem('sultra-view', state.view); document.querySelectorAll('[data-view]').forEach(item => item.classList.toggle('active', item === button)); $('#listings')?.classList.toggle('listing-feed-mode', state.view === 'feed'); }); }); $('#listings')?.classList.toggle('listing-feed-mode', state.view === 'feed'); state.compare = getCompareItems(); updateCompareTray(); renderRecentlyViewed(); $('#compare-open')?.addEventListener('click', () => { renderCompare(); $('#compare-dialog')?.showModal(); }); $('#compare-clear')?.addEventListener('click', () => setCompareItems([])); $('#compare-dialog .dialog-close')?.addEventListener('click', () => $('#compare-dialog').close()); $('#clear-recent')?.addEventListener('click', () => { localStorage.removeItem('sultra-recently-viewed'); renderRecentlyViewed(); toast('Riwayat listing dihapus.'); }); const rfq = $('#rfq-dialog'); const rfqForm = $('#rfq-form'); const rfqMessage = $('#rfq-message'); $('#rfq-open')?.addEventListener('click', () => rfq?.showModal()); $('#rfq-cancel')?.addEventListener('click', () => rfq?.close()); rfqForm?.addEventListener('submit', event => { event.preventDefault(); const data = Object.fromEntries(new FormData(rfqForm).entries()); const requests = readLocalArray('sultra-rfq'); writeLocalArray('sultra-rfq', [{ ...data, created_at: new Date().toISOString() }, ...requests], 10); if (rfqMessage) rfqMessage.textContent = 'Permintaan disimpan di perangkat ini. Bagikan detailnya ke seller saat menghubungi mereka.'; toast('RFQ tersimpan.'); setTimeout(() => rfq?.close(), 900); }); }

async function init() { setupTheme(); refreshFavoriteCount(); bindListingEvents(); setupPhase3(); setupRealtime(); setupDiscovery(); setupSidebarNavigation(); setupSellerForm(); setupDonation(); setupAdminDashboard(); window.SultraBridge?.initCommandPalette(); $('#suggestion-cta').onclick = () => location.href = 'mailto:halo@sultrakita.id?subject=Saran%20untuk%20SultraKita'; if ('serviceWorker' in navigator && !['localhost', '127.0.0.1'].includes(location.hostname) && !window.__TEST__) navigator.serviceWorker.register('/sw.js').catch(error => console.warn('[pwa]', error.message)); await Promise.all([setupLocations(), loadStats(), loadCategories()]); const url = new URL(location.href); $('#search').value = url.searchParams.get('q') || ''; state.category = url.searchParams.get('category') || ''; $('#district').value = url.searchParams.get('district') || ''; $('#sort').value = url.searchParams.get('sort') || 'newest'; renderCategories(); loadListings(); loadTrending(); track('page_view'); }

document.addEventListener('click', event => { const card = event.target.closest('[data-external-url]'); if (card && !event.target.closest('a,button')) window.open(card.dataset.externalUrl, '_blank', 'noopener,noreferrer'); });
document.addEventListener('DOMContentLoaded', () => init().catch(error => toast(error.message, 'error')));
